mapper.update:
update scheduler_task_lock set last_run = now(), owner = #{owner}
where task_name = #{taskName}
  and (last_run is null or last_run < DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:00'))

mapper.select:
select *
from meal_order

    is_deleted = 0
    and created_at >= #{startDate}
    and created_at < #{endDate} + INTERVAL 1 DAY

        and user_id = #{id}

select *
from room_order

    is_deleted = 0
    and created_at >= #{startDate}
    and created_at < #{endDate} + INTERVAL 1 DAY

        and user_id = #{id}

select checkin_time  as checkInTime,
       checkout_time as checkOutTime
from room_order
where room_id = #{roomId}
  and is_deleted = 0
  and checkin_time <= #{now}
  and checkout_time > #{now}
  and (pay_status = 1 or user_id is null)
  and status = 0

select *
from room_order
where room_id = #{id}
  and is_deleted = 0
  and checkin_time <= #{now}
  and checkout_time > #{now}
  and (pay_status = 1 or user_id is null)
  and status = 0
for update
